  this.scene=new T.Scene();this.scene.background=white;this.camera=new T.PerspectiveCamera(28,1,.1,2000);this.ortho=new T.OrthographicCamera(-50,50,50,-50,.1,2000);this.active=this.camera;this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.enableDamping=true;this.controls.maxPolarAngle=Math.PI/2-.01;this.controls.minDistance=15;this.controls.maxDistance=700;
