 box(w,h,d,x,y,z,material=this.paper,parent=this.root){if(w<=0||h<=0||d<=0)return null;const obj=new T.Mesh(this.geometry(new T.BoxGeometry(w,h,d)),material);obj.position.set(x,y,z);obj.castShadow=true;obj.receiveShadow=true;parent.add(obj);return obj;}
