   if(s.sign&&pallet(s.type)){const y=s.height+6;for(const x of [-s.width*.3,s.width*.3])this.box(.22,12,.22,x,s.height+2,-s.depth/2-1,this.metal);this.box(s.width*.72,5,.25,0,y,-s.depth/2-1,this.material(new T.MeshStandardMaterial({color:'#eceff1',roughness:.7})));}
